  let snaps=self.job.as_ref().map(|j|j.snapshot()).unwrap_or_default(); let all_terminal=!snaps.is_empty()&&snaps.iter().all(|d|matches!(d.phase,DestPhase::Done|DestPhase::Failed|DestPhase::Cancelled)); let starting=self.starting();let running=self.running_job()&&!all_terminal;let paused=running&&self.job.as_ref().is_some_and(|j|j.is_paused());let verifying=running&&snaps.iter().any(|d|d.phase==DestPhase::Verifying);let busy=starting||running;let now=Instant::now();
  if let Some(until)=self.error_flash_until{if now>=until{self.error_flash_until=None}else{ctx.request_repaint_after(until.saturating_duration_since(now));}} if starting{ctx.request_repaint_after(STARTING_REPAINT)}else if running{ctx.request_repaint_after(if paused{PAUSED_REPAINT}else{RUNNING_REPAINT})}else{ctx.request_repaint_after(THEME_CHECK_INTERVAL)}
  let key=self.paths_key();if key!=self.paths_key||self.last_path_check.elapsed()>=PATH_CHECK_INTERVAL{self.paths_key=key;self.last_path_check=Instant::now();self.path_errors=if busy{vec![]}else{self.validate_paths()};} let path_error_count=self.path_errors.len();let ready=!self.source.trim().is_empty()&&!self.dests.is_empty()&&path_error_count==0;
  egui::TopBottomPanel::top("header_v2").show(ctx,|ui|{ui.add_space(XS);ui.horizontal(|ui|{ui.heading(RichText::new("RepartoCopier").strong());if ui.available_width()>430.0{ui.label(RichText::new("Una carpeta · múltiples destinos").color(Theme::muted(self.use_light_theme)));}ui.with_layout(egui::Layout::right_to_left(egui::Align::Center),|ui|{if ui.add(egui::Button::new(RichText::new("⚙").size(17.0)).frame(false)).on_hover_text("Ajustes").clicked(){self.show_settings=true;}if starting{ui.weak("Validando…");}});});ui.add_space(XS);});
  egui::TopBottomPanel::bottom("footer_v2").show(ctx,|ui|{ui.horizontal(|ui|{let status=if paused{"Copia en pausa"}else if verifying{"Verificando integridad…"}else{&self.status};let color=if self.error_flash_until.is_some(){Theme::error(self.use_light_theme)}else if paused{Theme::warning(self.use_light_theme)}else if verifying{Theme::verify(self.use_light_theme)}else{Theme::muted(self.use_light_theme)};ui.colored_label(color,compact_path(status,72));ui.with_layout(egui::Layout::right_to_left(egui::Align::Center),|ui|{if ui.small_button("Acerca de").clicked(){self.show_credits=true;}});});});
