   ui.add_space(XS);ui.label(RichText::new("ORIGEN").small().strong().color(Theme::muted(self.use_light_theme)));ui.horizontal(|ui|{let button_w=86.0;let field_w=(ui.available_width()-button_w-SM).max(120.0);ui.add_enabled_ui(!busy,|ui|{ui.add_sized([field_w,30.0],egui::TextEdit::singleline(&mut self.source).hint_text("Selecciona la carpeta que quieres copiar"));if ui.add_sized([button_w,30.0],egui::Button::new("Examinar")).clicked(){if let Some(p)=Self::pick_dir(){self.source=p;}}});});
   ui.add_space(MD);ui.horizontal(|ui|{ui.label(RichText::new(format!("DESTINOS  ({})",self.dests.len())).small().strong().color(Theme::muted(self.use_light_theme)));ui.add_enabled_ui(!busy,|ui|{if ui.small_button("+ Agregar").clicked(){if let Some(p)=Self::pick_dir(){if !self.dests.contains(&p){self.dests.push(p)}}}});});
   egui::ScrollArea::vertical().id_salt("destinations_v2").max_height(130.0).show(ui,|ui|{let mut remove=None;for(i,d)in self.dests.iter().enumerate(){card_frame(self.use_light_theme).show(ui,|ui|{ui.horizontal(|ui|{ui.weak(format!("{:02}",i+1));let chars=((ui.available_width()/7.2)as usize).clamp(18,72);ui.label(compact_path(d,chars)).on_hover_text(d);if let Some(p)=snaps.get(i){let(label,color)=phase_label(p.phase,p.files_err,self.use_light_theme,paused);ui.colored_label(color,label);}ui.with_layout(egui::Layout::right_to_left(egui::Align::Center),|ui|{if !busy&&ui.small_button("×").on_hover_text("Quitar destino").clicked(){remove=Some(i);}});});});ui.add_space(XS);}if let Some(i)=remove{self.dests.remove(i);}});
