   ui.horizontal_wrapped(|ui|{ui.add_enabled_ui(!busy,|ui|{ui.checkbox(&mut self.skip_same,"Omitir iguales").on_hover_text("Evita copiar de nuevo archivos que ya coinciden.");ui.checkbox(&mut self.keep_going,"Continuar con errores").on_hover_text("Los demás destinos continúan si uno falla.");});ui.with_layout(egui::Layout::right_to_left(egui::Align::Center),|ui|{if running{if let Some(j)=&self.job{if ui.button("Cancelar").clicked(){j.request_cancel();}if ui.button(if paused{"Continuar"}else{"Pausar"}).clicked(){j.set_paused(!paused);}}}else if !starting&&ui.add_enabled(ready,egui::Button::new(RichText::new("Iniciar copia").strong())).clicked(){self.start();}});});
